// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

import "./libraries/NFTDescriptor.sol";

contract NonfungibleTokenPositionDescriptor {
    address public immutable WETH9;

    constructor(address _WETH9) {
        WETH9 = _WETH9;
    }

    function tokenURI(uint256 tokenId) external view returns (string memory) {
        if (WETH9 == address(0)) return "";
        return NFTDescriptor.constructTokenURI(tokenId);
    }
}

contracts/libraries/NFTDescriptor.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

import "./StrUtil.sol";

library NFTDescriptor {
    function constructTokenURI(uint256 tokenId) public pure returns (string memory) {
        return StrUtil.toHexPrefix(tokenId);
    }
}

contracts/libraries/StrUtil.sol.content:
// SPDX-License-Identifier: MIT
pragma solidity =0.7.6;

library StrUtil {
    function toHexPrefix(uint256 value) internal pure returns (string memory) {
        if (value == 0) return "0x0";
        return "0x1";
    }
}
